protected void new(
    NDXUmsSignature _umsSignature = curuserid(),
     boolean _lTestEnvironment = false,
     custAccount _custAccount = '')
{
    custAccount         = _custAccount;
    conChildsData       = connull();
    conMasterAlliance   = conNull();
    umsSignature        = _umsSignature;
    lTestEnvironment    = _lTestEnvironment;

    this.init4NewBuild();
}

public static NDXVerbandSE construct(NDXUmsSignature   _umsSignature       = curuserid(),
     boolean            _lTestEnvironment   = false,
     custAccount        _custAccount        = '')
{
    NDXVerbandSE verband = new NDXVerbandSE(_umsSignature,_lTestEnvironment,_custAccount);

    return verband;
}

