/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "lWithInfo">boolean</param>
static void buildAllianceTree(boolean lWithInfo = false)
{
    ;
    if (lWithInfo)
    {
        info(strfmt('[%1] Start: Ermittlung der Verbandstrukturen und deren Debitoren', NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))));
    }
    // Ermittlung aller Verbandsstrukturen in tables.NDX_AllianceTree
    NDXVerbandSE::getAllianceParentChild();
    // Debitoren aller Unterverbände ermitteln
    NDXAllianceTreeCustomer::buildFromNDXAllianceTree();
    if (lWithInfo)
    {
        info(strfmt('[%1] Ende: Ermittlung der Verbandstrukturen und deren Debitoren', NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))));
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
static void getAllianceParentChild()
{
    CustTable               c1, c2, c3, allianceRoot;
    KCS_TOSTable            tosTable1, tosTableRoot;
    NDXAllianceTree         nDXAllianceTree;
    NDXUmsatzClass          nDXUmsatzClass;
    KCS_BOSAllianceID       allianceRootID;
    container               conFirmen;
    int                     i;
    dataAreaId              company;
    NDXCompanys             firma;

    void getValue(AVATOSId l_alliance, int level = 2)
    {
        KCS_TOSTable tosTable;

        while select tosTable
            where tosTable.ParentTosId == l_alliance
        {
            //info(strfmt('Alliance [%3] Level [%2] AccountNum [%1]', l_c1.AccountNum, level, l_alliance));
            NDXAllianceTree::insertRecords(firma, allianceRootID, l_alliance, tosTable.TosId, 0, level);
            getValue(tosTable.TosId, level + 1);
        }
    }
    ;

    //--> 1.1: NDX/PAFFH/NDX_TASK1235003633/18.12.2014
    nDXUmsatzClass = NDXUmsatzClass::construct();
    conFirmen = nDXUmsatzClass.parmConFirmen();
    //<-- NDX/PAFFH/NDX_TASK1235003633/18.12.2014


    // alte Einträge bereinigen
    delete_from nDXAllianceTree;

    //--> 1.1: NDX/PAFFH/NDX_TASK1235003633/18.12.2014
    for (i=1; i <= conlen(conFirmen); i++)
    {
        firma = conpeek(conFirmen, i);
        company = NDXHelperCommon::NDXCompanys2CompanyId(firma);

        changecompany(company)
        {
            //<-- NDX/PAFFH/NDX_TASK1235003633/18.12.2014
            tosTableRoot    = null;
            tosTable1       = null;
            allianceRoot    = null;
            c1              = null;
            c2              = null;
            c3              = null;
            // Schleife über alle Root-Verbände
            //TODO DebuC durch KCS_TOSTAble tauschen
            //while select        KCS_BOSAllianceID
            //from            allianceRoot
            //order by        KCS_BOSAllianceID
            //group by        KCS_BOSAllianceID
            //where           allianceRoot.KCS_BOSAllianceID
            //notexists join  c3
            //    where       c3.AccountNum == allianceRoot.KCS_BOSAllianceID && c3.KCS_BOSAllianceID
            while select tosTableRoot
                where tosTableRoot.ParentTosId == ''
            {
                allianceRootID = tosTableRoot.TOSId;
                //c4 = CustTable::find(allianceRootID);
                NDXAllianceTree::insertRecords(firma, allianceRootID, tosTableRoot.TOSId, tosTableRoot.TOSId, 0, 0);
                // Schleife über alle Mittglieder der 1.Ebene des Verbands
                //while select    AccountNum, Party
                //from        c1
                //group by    AccountNum, Party
                //where       c1.KCS_BOSAllianceID == allianceRoot.KCS_BOSAllianceID
                //exists join c2
                //    where   c2.KCS_BOSAllianceID == c1.AccountNum
                while select tosTable1
                    where tosTable1.ParentTosId == tosTableRoot.TosId
                {
                    //info(strfmt('Alliance [%3] Level [%2] AccountNum [%1]', c1.AccountNum, 1, alliancRoot.KCS_BOSAllianceID));
                    NDXAllianceTree::insertRecords(firma, allianceRootID, tosTable1.ParentTosId, tosTable1.TosId, 0, 1);
                    // Unterverbände abarbeiten
                    getValue(tosTable1.TosId);
                }
            }
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 05.02.25
/// </summary>
/// <param name = "conFirmen">container</param>
/// <param name = "threadControl">NDXTmpUmsatzClassThreadControl</param>
/// <param name = "_storeCopyFrom">NDXCentralStoreId</param>
void getCSFromMaster(container conFirmen = [NDXHelperCommon::CompanyId2NDXCompany(curext(), lTestEnvironment)],
                 NDXTmpUmsatzClassThreadControl threadControl = null,
                 NDXCentralStoreId _storeCopyFrom = '') 
{
    NDX_CentralStore    nDX_CentralStore;
    int                     i, nBis, nAnz = 0;
    custAccount             lcustAccount;
    container               conDataArea;
    str                     text;
    container               lconFirmen = conFirmen;

    if (!lgotCSFromMaster)
    {
        if (!lconFirmen)
        {
            lconFirmen = [NDXHelperCommon::CompanyId2NDXCompany(curext(), lTestEnvironment)];
        }

        //TODO PaffH: checkpoint NDXTmpVerband
        delete_from nDXTmpVerband
        where   nDXTmpVerband.UmsSignature == umsSignature;

        conDataArea = NDXHelperCommon::NDXCompanys2CompanyIdImpCon(lconFirmen, lTestEnvironment);

        nBis = conlen(conChilds);
        for (i = 1; i <= nBis; i++)
        {
            lcustAccount = conpeek(conChilds, i);
            while select crosscompany:conDataArea  nDX_CentralStore
                where       nDX_CentralStore.CentralStoreId == lcustAccount &&
                            nDX_CentralStore.Deaktiv        == NoYes::No
            {
                if (nDX_CentralStore && nDX_CentralStore.CentralStoreId != _StoreCopyFrom)
                {
                    ttsbegin;
                    //TODO PaffH: checkpoint NDXTmpVerband
                    nDXTmpVerband = NDXTmpVerband::find(nDXTmpVerband, umsSignature, nDX_CentralStore.dataAreaId, nDX_CentralStore.CentralStoreId, true);
                    nDXTmpVerband.UmsSignature     = umsSignature;
                    nDXTmpVerband.CentralStoreId   = nDX_CentralStore.CentralStoreId;
                    nDXTmpVerband.Company          = nDX_CentralStore.dataAreaId;
                    if (nDXTmpVerband.validateWrite())
                    {
                        nDXTmpVerband.write();
                    }
                    ttscommit;
                    ++nAnz;

                    if (threadControl && (nAnz mod 10 == 0))
                    {
                        text = strfmt("@NDX:NDXCentralWarehouseNumber", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), nAnz, nDX_CentralStore.CentralStoreId); // [%1] Zentrallager: Nr. [%2] [%3]
                        NDXTmpUmsatzClassThreadControl::setInfoStatic(threadControl, text, true);
                    }
                }
            }
        }
        lgotCSFromMaster = true;
    }
}

