/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 05.02.25
/// </summary>
/// <param name = "lSaveToTable">boolean</param>
/// <param name = "conCompany">container</param>
/// <returns>container</returns>
container getChildsFromMaster(boolean lSaveToTable = false, container conCompany = [curext()])
{
    NDXTmpCustomerAlliance     nDXTmpCustomerAlliance;
    CustTable                   custTableBOSAlliance;
    CustTable                   custTable, custTable2;

    AVATOSId                    kCS_BOSAllianceID;
    int                         i, j;
    CompanyId                   companyId;
    //NDXRecordBlockContract blockContract;
    Set set1 = new Set(Types::Int64);


    // rekursiver Aufruf zur Ermittlung der Struktur-Aufhänger
    void getMasters(AVATOSId _Master)
    {
        KCS_TOSTable    tosTable;
        ;
        while select    tosTable
        where       tosTable.ParentTOSId  == _Master
        {
            conMasters      += tosTable.TOSId;
            getMasters(tosTable.TOSId);
        }
    }
    ;

    if (!lgotChildsFromMaster)
    {
        for (j = 1; j <= conlen(conCompany); j++)
        {
            companyId = conpeek(conCompany, j);
            firma = NDXHelperCommon::CompanyId2NDXCompany(companyId);

            if (lSaveToTable)
            {
                //TODO PaffH: checkpoint NDXTmpVerband
                delete_from nDXTmpCustomerAlliance
                where   nDXTmpCustomerAlliance.UmsSignature    == umsSignature     &&
                        nDXTmpCustomerAlliance.Alliance        == masterAlliance   &&
                        nDXTmpCustomerAlliance.Company         == firma;
                //blockContract = NDXTmpCustomerAllianceBlock::blockCheck(umsSignature, masterAlliance, firma, true);
                //if (blockContract.parmBlocked() == NoYes::Yes)
                //{
                //    while select RecId from nDXTmpCustomerAlliance
                //    where nDXTmpCustomerAlliance.UmsSignature == umsSignature
                //    && nDXTmpCustomerAlliance.Alliance == masterAlliance
                //    && nDXTmpCustomerAlliance.Company == firma
                //    {
                //        set1.add(nDXTmpCustomerAlliance.RecId);
                //    }
                //}
            }

            conMasters      = connull();
            conChilds       = connull();
            conChildsMaster = connull();

            changecompany(companyId)
            {
                custTable   = null;
                custTable2  = null;
                custTableBOSAlliance = CustTable::find(masterAlliance);

                if (!masterAlliance)
                {
                    this.getMaster();
                }

                if (!masterAlliance)
                {
                    return conChilds;
                }

                // Aufhänger ermitteln
                getMasters(masterAlliance);

                conMasters += masterAlliance;

                // Clients aus den Strukturen ermitteln
                for (i=1; i<=conlen(conMasters); i++)
                {
                    kCS_BOSAllianceID   = conpeek(conMasters,i);
                    // Alle Kunden der Struktur durchlaufen
                    // alle selektieren, aussern denen die ebenfalls eine Struktur bilden
                    while select        custTable
                    where           custTable.KCS_TOSId == kCS_BOSAllianceID
                    notexists join  custTable2
                        where       custTable2.KCS_TOSId == custTable.AccountNum
                    {
                        conChilds       += custTable.AccountNum;
                        conChildsMaster += kCS_BOSAllianceID;
                        if (lSaveToTable)
                        {
                            //if (blockContract && blockContract.parmBlocked())
                            {
                                nDXTmpCustomerAlliance = NDXTmpCustomerAlliance::findOrCreate(
                                umsSignature, masterAlliance, kCS_BOSAllianceID, custTable.AccountNum, firma, custTableBOSAlliance.Party, custTable.Party, false);
                                if (nDXTmpCustomerAlliance)
                                {
                                    set1.remove(nDXTmpCustomerAlliance.RecId);
                                }
                                else
                                {
                                    nDXTmpCustomerAlliance.insert();
                                }
                            }
                        }
                    }
                    if (lSaveToTable)
                    {
                        //if (blockContract && blockContract.parmBlocked())
                        {
                            ttsbegin;
                            SetEnumerator enum = set1.getEnumerator();
                            while (enum.moveNext())
                            {
                                delete_from nDXTmpCustomerAlliance
                                where nDXTmpCustomerAlliance.RecId == enum.current();
                            }
                            ttscommit;
                            //NDXTmpCustomerAllianceBlock::unblock(umsSignature, masterAlliance, firma);
                        }
                    }
                }
            }
            nAnzChilds += conlen(conChilds);
        }
        lgotChildsFromMaster = true;
    }
    return conChilds;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <param name = "companyId">CompanyId</param>
/// <returns>container</returns>
NDXMasterAllianceStructure getMaster(CustAccount _custAccount = custAccount,
                CompanyId     companyId = curext())
{
    CustTable                   custTableBOSAlliance;
    CustTable                   custTable;
    KCS_TOSTable                tosTable;
    KCS_TOSTable                tosTableAlliance;
    NDXMasterAllianceStructure  masterAllianceStructure;

    AVATOSId                    lmasterAlliance;
    ;
    custAccount             = _custAccount;
    conMasterAlliance       = conNull();

    changecompany(companyId)
    {
        masterAllianceStructure = NDXMasterAllianceStructure::construct();
        tosTable                = null;
        tosTableAlliance        = null;
        custTable               = null;
        custTableBOSAlliance    = null;
        //TODO: DebuC austauschen durch KCS_TOSTable
        //--> 1.4: NDX/PAFFH/NDX_TASK1235003633/05.04.2014
        //select firstOnly custTableBOSAlliance where custTableBOSAlliance.KCS_BOSAllianceID == custAccount;
        select firstonly tosTable where tosTable.TosId == CustTable::find(custAccount).KCS_TOSId;

        if (tosTable)
        {
            masterAllianceStructure.addMasterAlliance(custAccount, NDXMasterAllianceType::AccountNum);
        }

        //<-- NDX/PAFFH/NDX_TASK1235003633/05.04.2014

        custTableBOSAlliance    = CustTable::find(custAccount);

        lmasterAlliance         = custTableBOSAlliance.KCS_TOSId;
        if (lmasterAlliance)
        {
            masterAllianceStructure.addMasterAlliance(lmasterAlliance, NDXMasterAllianceType::TOSId);

            while (tosTable.ParentTosId)
            {
                tosTable = KCS_TOSTable::find(lmasterAlliance);
                if (tosTable && tosTable.ParentTosId)
                {
                    lmasterAlliance     = tosTable.ParentTosId;
                    masterAllianceStructure.addMasterAlliance(lmasterAlliance, NDXMasterAllianceType::TOSId);
                }
                else
                {
                    break;
                }
            }
        }
        else
        {
            //--> 1.1: NDX/PaffH/21.09.2010
            // Falls custTableBOSAlliance.KCS_BOSAllianceID nicht gefüllt ist,
            // kann es sein dass es sich um die oberste Ebene handelt
            select firstOnly tosTableAlliance where tosTableAlliance.ParentTosId == tosTable.TosId;
            if (custTable)
            {
                lmasterAlliance     = tosTable.TosId;
                masterAllianceStructure.addMasterAlliance(lmasterAlliance, NDXMasterAllianceType::TOSId);
            }
            //<-- NDX/PaffH/21.09.2010
        }
    }

    lMasterAllianceChanged  = (masterAlliance != lmasterAlliance);
    masterAlliance          = lmasterAlliance;
    masterAllianceStructure.parmMasterAlliance(masterAlliance);
    return masterAllianceStructure;
}

