/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "conDataArea">container</param>
/// <returns>int</returns>
static int getMasters(container  conDataArea = [curext()])
{
    CustTable           custTable;
    NDXMasterAlliance   nDX_MasterAlliance;

    int                 nAnzMasters, i, j;
    NDXVerbandSE          nDX_Verband;
    NDXUmsSignature     umsSignature = curuserid();

    //--> 1.1: NDX/PAFFH/NDX_TASK1235003759/07.11.2014
    Query                       q = new Query();
    QueryBuildDataSource        qbds;
    QueryRun                    qr;
    Set                         setOld = new Set(Types::Container);
    Set                         setNew = new Set(Types::Container);
    Set                         setDel = new Set(Types::Container);
    Set                         setApp = new Set(Types::Container);
    SetEnumerator               enum;
    CompanyId                   company;
    NDXMasterAllianceType       type;
    AVATOSId                    allianceMaster;
    NDXMasterAllianceStructure  masterAllianceStructure;
    MapEnumerator               masterAllianceMapEnumerator;
    //<-- NDX/PAFFH/NDX_TASK1235003759/07.11.2014

    ;
    //--> 1.1: NDX/PAFFH/NDX_TASK1235003759/07.11.2014
    qbds = q.addDataSource(tablenum(NDXMasterAlliance));
    for (i=1; i<=conlen(conDataArea); i++)
    {
        qbds.addRange(fieldnum(NDXMasterAlliance, Company)).value(conpeek(conDataArea, i));
    }
    qr = new QueryRun(q);
    while (qr.next())
    {
        nDX_MasterAlliance = qr.get(tablenum(NDXMasterAlliance));
        setOld.add([ nDX_MasterAlliance.Company, nDX_MasterAlliance.AllianceMaster, nDX_MasterAlliance.Type]);
    }

    //delete_from nDX_MasterAlliance;
    //<-- NDX/PAFFH/NDX_TASK1235003759/07.11.2014

    nDX_Verband = NDXVerbandSE::construct(umsSignature, false);
    for (j=1; j <= conlen(conDataArea); j++)
    {
        company = conpeek(conDataArea, j);
        changecompany(company)
        {
            custTable = null;
            while select custTable
            {
                masterAllianceStructure  = nDX_Verband.getMaster(custTable.AccountNum, custTable.dataAreaId);
                masterAllianceMapEnumerator = masterAllianceStructure.getMasterAllianceEnumerator();
                while(masterAllianceMapEnumerator.moveNext())
                {
                    if (setNew.add([custTable.dataAreaId, masterAllianceMapEnumerator.currentKey(),masterAllianceMapEnumerator.currentValue()]))
                    {
                        ++nAnzMasters;
                    }
                }
            }
        }
    }

    // Einträge löschen
    setDel = Set::difference(setOld, setNew);
    enum = setDel.getEnumerator();
    while (enum.moveNext())
    {
        company         = conpeek(enum.current(), 1);
        allianceMaster  = conpeek(enum.current(), 2);
        type            = conPeek(enum.current(), 3);
        nDX_MasterAlliance = NDXMasterAlliance::find(allianceMaster, company,type, true);
        if (nDX_MasterAlliance)
        { 
            ttsbegin;
            nDX_MasterAlliance.delete();
            ttscommit;
        }
    }
    // Einträge anfügen
    setApp = Set::difference(setNew, setOld);
    enum = setApp.getEnumerator();
    while (enum.moveNext())
    {
        company         = conpeek(enum.current(), 1);
        allianceMaster  = conpeek(enum.current(), 2);
        type            = conPeek(enum.current(), 3);
        nDX_MasterAlliance = NDXMasterAlliance::find(allianceMaster, company, type);
        if (!nDX_MasterAlliance)
        {
            nDX_MasterAlliance.AllianceMaster   = allianceMaster;
            nDX_MasterAlliance.Company          = company;
            nDX_MasterAlliance.Type             = type;
            nDX_MasterAlliance.insert();
        }
    }

    return nAnzMasters;
}

